"""Request field parser."""


def parse_fields(raw):
    if raw is None:
        return {}
    fields = {}
    for line in raw.splitlines():
        if not line.strip() or '=' not in line:
            continue
        key, value = line.split('=', 1)
        fields[key.strip()] = value.strip()
    return fields

ts12_06_migration.src/cli.py:
"""Tiny option parser."""


def parse_args(argv):
    options = {"value": None, "deprecated": []}
    index = 0
    while index < len(argv):
        token = argv[index]
        if token in ("--new-flag", "--old-flag"):
            options["value"] = argv[index + 1]
            if token == "--old-flag":
                options["deprecated"].append("--old-flag")
            index += 2
            continue
        raise SystemExit("unknown option: " + token)
    return options

